-- 6. Wire current_version_id ---------------------------------------------
UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:vehicle-master','pico:gate-master') AND current_version_id IS NULL;
